#!/bin/bash
# test-maclockscreen.sh: Mac Lock Screen's plain rules (common/MacLockScreen.h, F49 1.8.9 rev 2) -- see test-maclockscreen.m. Then made-to-fail
# copies of the header, each must fail: rev 1's defaults and sizes, the first pass's three sequence faults (a stale lock, a switcher flag only its cleanup
# clears, the first face only at -viewWillAppear:), the zone clamp, the measured macOS sizes and places (12.4a), the hint line's place, yield,
# look and pick, the pair's order, the crop, the depth rule; 1.8.9 pass: the black backdrop: the 17/18 sharp default, Blurred's offer there, the empty-still guard,
# the backdrop key's version.
cd "$(dirname "$0")" || exit 1
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
H=${MLS_H:-../common/MacLockScreen.h}
build() {   # $1 header, $2 out
  mkdir -p "$(dirname "$2")"; cp "$1" "$(dirname "$2")/MacLockScreen.h"; cp ../common/MacLockCoexist.h "$(dirname "$2")/"
  clang -fobjc-arc -Wall -Wno-unused-function -DMLS_HEADER="\"$(dirname "$2")/MacLockScreen.h\"" -framework Foundation -framework CoreGraphics -framework QuartzCore -o "$2" test-maclockscreen.m 2> "$2.cc" || { cat "$2.cc"; return 99; }
  [ -s "$2.cc" ] && { echo "FAIL  warnings:"; cat "$2.cc"; return 98; }
  return 0
}
build "$H" "$W/real/t" || { echo "FAIL  the real header did not build"; exit 1; }
"$W/real/t"; rc=$?
# ---- the wiring in macsettings/MacLockScreen.x (rev 2): where the machine, the switcher state and the face retries are called ----
X=${MLS_X:-../macsettings/MacLockScreen.x}
check() { if eval "$2"; then echo "PASS  $1"; else echo "FAIL  $1"; rc=1; fi; }
meth() { awk -v s="$1" 'index($0, s) == 1 {f=1} f {print} f && /^}/ {exit}' "$X"; }
check "viewWillAppear: the machine once, then the face" "meth '- (void)viewWillAppear:(BOOL)animated {' | awk '/MLAppearMachine\(self\);/{a=NR} /MLFaceTry\(self, \"viewWillAppear\"\);/{b=NR} END{exit !(a && b > a)}'"
check "the face at the Cover Sheet view's first layout in its window, and at -didMoveToWindow (12.2 (1))" "meth '- (void)layoutSubviews {' | grep -qF 'MLFaceTry(cs, \"the first layout\")' && meth '- (void)didMoveToWindow {' | grep -qF 'MLFaceTry(cs, \"didMoveToWindow\")'"
check "viewDidAppear: the last chance, logged as late" "meth '- (void)viewDidAppear:(BOOL)animated {' | grep -qF 'if (MLFaceTry(self, \"viewDidAppear\")) MLLog(@\"the face came late: at viewDidAppear\");'"
check "the switcher: begun at its prepare, read after it, ended by the screen-off and the disappearance (12.2 (2))" "meth '- (void)_prepareForPosterSwitcherPresentation {' | grep -qF 'MLSwitcherBegin(&gSw);' && [ \$(grep -c 'if (off) { MLOnScreenOff(&gM); MLSwitcherEnd(&gSw); return; }' $X) = 2 ] && meth 'static void MLGone(void) {' | grep -qF 'MLSwitcherEnd(&gSw);'"
check "the switcher's cleanup brings the face back only when it has ended" "meth '- (void)_cleanupPosterSwitcherPresentationForCompleted:(BOOL)completed withActivatingTouches:(id)touches {' | grep -qF 'if (!gSw.pending) MLFaceTry(self, \"the poster switcher has gone\");'"
check "the wake reads iPadOS's lock-or-pull again (12.2 (3) a)" "meth 'static void MLWake(CSCoverSheetViewController *cs) {' | grep -qF 'MLOnScreenOn(&gM, MLDismissedRead());'"
check "a master switch resets the machine; switched on, an appearance only on a SHOWN Cover Sheet (12.2 (3) b, c)" "meth 'static void MLPrefsChanged(void) {' | grep -qF 'if (wasOn != gS.enabled) MLOnMasterSwitch(&gM);' && meth 'static void MLPrefsChanged(void) {' | awk '/if \(!MLInMainWindow\(cs\)\) return;/{a=NR} /if \(!wasOn\) \{ MLAppearMachine\(cs\); MLFaceTry\(cs, \"switched on\"\); \}/{b=NR} END{exit !(a && b > a)}'"
check "the pair from what IS drawn (common/LockBarHide.h), never from Hide Status Bar on Lock Screen's preference (12.1)" "meth 'static void MLStatusDecide(const char *why) {' | grep -qF 'BOOL shows = LBHPairShows(f);' && ! grep -q 'hideStatusBar' $X && meth 'static void MLPairLayout(UIView *cv) {' | grep -qF 'if (!gPairShows) { if (gPair) MLPairDrop(); return; }'"
check "the band dropped only while our pair draws (A22, 12.1)" "meth 'static void MLBandLayout(UIView *cv) {' | grep -qF 'MLHideIn(&gBandHidden, band, gPairShows);'"
check "read again at each Cover Sheet layout pass and a turn after SpringBoard's Lock Screen bar requests" "meth 'static void MLLayoutCoverParts(UIView *cv) {' | grep -qF 'MLStatusDecide(\"a layout pass\");' && awk '/^%group MLStatusWatch/{f=1} f&&/MLStatusSoon\(\);/{n++} f&&/^%end$/{e++} e==2{exit} END{exit !(n == 2)}' $X"
check "iPadOS's own bar given back at the dismissal's start, at a drop and when the part is not in force (Q27)" "meth '- (void)viewWillDisappear:(BOOL)animated {' | grep -qF 'if (LBHReasonIn()) LBHSet(self, NO);' && meth 'static void MLDropAll(NSString *why) {' | grep -qF 'if (LBHReasonIn()) LBHSet(gCS, NO);' && meth 'static void MLGiveBackParts(void) {' | grep -qF 'if (LBHReasonIn()) LBHSet(gCS, NO);'"
check "the hint: no field of ours = every hint view of iPadOS's drawn (one hint drawing, never none)" "meth 'static BOOL MLFieldMirror(void) {' | grep -qF 'if (!show) { MLHintUnmaskViews(); u.field.hidden = YES; return NO; }' && meth '- (void)viewWillDisappear:(BOOL)animated {' | grep -qF 'MLHintUnmaskAll();'"
check "the hint's mask never replaces a mask of iPadOS's or another's" "meth 'static BOOL MLHintMask(UIView *v) {' | grep -qF 'if (v.layer.mask) return NO;'"
check "the field's hooks only where no other modification changes the hint line (12.6)" "grep -qF 'gFieldOwned = MLHintMethodsForeign(YES);' $X && grep -qF 'if (!gFieldOwned && objc_getClass(\"SBUICallToActionLabel\") && objc_getClass(\"SBUILegibilityLabel\") && ML_TYPES_OK(MLHint)) %init(MLHint);' $X"
check "17/18: the time placed under a date line iPadOS keeps (review finding 1)" "grep -qF 'if (!dateDrawn) top = MLClockKeptTop(top, keptLineBottom, S);' $X && meth 'static void MLClockLayout17(UIView *pd) {' | grep -qF 'MLClockPlace(host, time, sub, plainDate, [NSDate date], zone, columnRight, kept);'"
check "the wake: a changed pair decision laid out at once; a switcher still up starts its state again (review 6, 13)" "meth 'static void MLWake(CSCoverSheetViewController *cs) {' | grep -qF 'else if (pairWas != gPairShows) [MLCoverView() setNeedsLayout];' && meth 'static void MLWake(CSCoverSheetViewController *cs) {' | grep -qF 'MLSwitcherBegin(&gSw); MLSwitcherRead(&gSw, YES);' && [ \$(grep -c '    MLWake(self);' $X) = 2 ]"
check "the dismissal's start drops our pair whoever hid the bar (review 7)" "meth '- (void)viewWillDisappear:(BOOL)animated {' | grep -qF 'gPairShows = NO; MLPairDrop(); MLGiveBackBand();'"
check "off the main page our field is hidden and iPadOS's hint drawn (review 3); any hint candidate's change re-picks (review 4)" "meth 'static BOOL MLFieldMirror(void) {' | grep -qF '!gFieldPaging' && meth 'static void MLPairFollowPages(CSCoverSheetViewController *cs, UIScrollView *sv) {' | grep -qF 'MLFieldFollowPages(dx);' && [ \$(grep -c 'if (gUser && MLIsHintCand((UIView \*)self)) MLHintChanged((UIView \*)self);' $X) = 10 ]"
check "Q27 asked with Hide Status Bar on Lock Screen's flag, the page's wish and Today (review 2, 5)" "meth 'static void MLStatusDecide(const char *why) {' | grep -qF 'BOOL want = LBHPartHides(partOn, b.drawn, b.ourMenuBar, LBHReasonIn(), hidByLSB, page, today);'"
check "the time: tracked between its glyphs only, set only when its text, size, weight or colour changed (review of the Q28 look, 3 and 8)" "meth 'static void MLClockPlace(' | grep -qF 'if (tas.length > 1) [tas addAttribute:NSKernAttributeName value:@(MLMacTimeKern(c.timeSize)) range:NSMakeRange(0, tas.length - 1)];' && meth 'static void MLClockPlace(' | grep -qF 'if (![gClockTimeKey isEqualToString:tkey]) {' && ! meth 'static void MLClockPlace(' | grep -q 'isEqualToAttributedString' && meth 'static void MLClockPlace(' | grep -qF 'CGFloat tw1 = MLMacTimeWidth1('"
check "the hint line follows new words at once, resized around its centre (review of the Q28 look, 2)" "meth 'static BOOL MLFieldMirror(void) {' | grep -qF 'if (fabs(f.size.width - w) >= 0.5) { u.field.frame = CGRectMake(round(CGRectGetMidX(f) - w / 2), f.origin.y, w, f.size.height);'"
check "a hint group not as written for this iPadOS: our line stands down, iPadOS's own drawn (review of the hook types, 4)" "grep -qF 'if (!gFieldOwned && !(ML_TYPES_OK(MLHint) && ML_TYPES_OK(MLHintCTA) && ML_TYPES_OK(MLHint17) && ML_TYPES_OK(MLHint17b))) { gFieldOwned = YES;' $X"
check "17/18: the poster's identity by the typed routes 17.5.1 and 18.5 answer, no KVC at an appearance (1.8.9 pass: the black backdrop)" "meth 'static NSString *MLBackdropSource(void) {' | grep -qF 'if (gOS >= 17) return MLPosterSource(MLIvar(MLWallpaperController(), \"_activeLockScreenPosterConfiguration\"));' && ! meth 'static NSString *MLBackdropSource(void) {' | grep -qE 'valueForKey|@try|posterUUID'"
check "the clock's hosts, type table and hooks by what draws iPadOS's clock (16-18 the prominent display, 15 the date view), never by '17 or later' (1.8.9 pass: two clocks on 16)" "meth 'static int MLClockPath(void) {' | grep -qF 'MLClockPathOf(objc_getClass(\"CSProminentDisplayView\"), objc_getClass(\"CSProminentTimeView\"), objc_getClass(\"SBFLockScreenDateView\"))' && meth 'static BOOL MLHostTypes(int p) {' | grep -qF 'case kMLPartClock: return MLClockPath() != kMLClockPathNone;' && meth 'static BOOL MLPartTypesOK(int p) {' | grep -qF 'case kMLPartClock: return MLProminentClock() ? ML_TYPES_OK(MLClock17) : ML_TYPES_OK(MLClock15);' && grep -qF 'case kMLPartClock: if (MLProminentClock()) { %init(MLClock17); } else { %init(MLClock15); } break;' $X && ! grep -E 'gOS *(>=|<) *1[67]' $X | grep -qiE 'clock|prominent|transient|MLHostTypes'"
check "the empty-still guard: the still checked before the blur in a zeroed context, an empty one never stored or shown, its key not read again (the black backdrop, option b)" "meth 'static UIImage *MLBlurred(' | awk '/memset\(CGBitmapContextGetData\(ctx\), 0, H \* CGBitmapContextGetBytesPerRow\(ctx\)\);/{a=NR} /CGContextDrawImage\(ctx,/{b=NR} /if \(!b.data \|\| MLStillEmpty\(b.data, W, H, b.rowBytes\)\) \{ if \(empty\) \*empty = b.data != NULL; CGContextRelease\(ctx\); return nil; \}/{c=NR} /MLBoxBlur\(&b, 6\)/{d=NR} END{exit !(a && b > a && c > b && d > c)}' && meth 'static void MLBackdropMake(' | awk '/UIImage \*img = MLBlurred\(src, screen, contrast, &empty\);/{a=NR} /if \(empty\) \{/{b=NR} /\[gEmptyKeys addObject:key\];/{c=NR} /^                    return;/{d=NR} /gBackdropImage = img; gBackdropKeyShown = key;/{e=NR} END{exit !(a && b > a && c > b && d > c && e > d)}' && meth 'static void MLBackdropPrepare(' | awk '/if \(\[gEmptyKeys containsObject:key\]\) \{ gBackdropImage = nil; gBackdropKeyShown = nil; return; \}/{a=NR} /MLBackdropKeyMatches\(disk, key\)/{b=NR} /MLBackdropMake\(key/{c=NR} END{exit !(a && b > a && c > b)}'"
check "Blurred offered on 17/18 only after a real still: stillRead written to the state file, set only from Blurred's still (made, or from the disk) (1.8.9 pass: the black backdrop)" "grep -qF 'NSDictionary *d = MLStateDict(why, gNoStill, gStillRead);' $X && [ \$(grep -c 'gStillRead = YES' $X) = 2 ] && meth 'static void MLBackdropMake(' | grep -qF 'if (wallpaperStill && gOS >= 17 && gS.enabled && !gStillRead) { gStillRead = YES; MLWriteState(); }' && meth 'static void MLBackdropMake(' | grep -qF 'BOOL wallpaperStill = gS.background == kMLBackBlurred;' && meth 'static void MLBackdropPrepare(' | grep -qF 'if (gS.background == kMLBackBlurred && gOS >= 17 && !gStillRead) { gStillRead = YES; MLWriteState(); }'"
check "the depth effect hidden only while our picture is up (an empty still leaves iPadOS's wallpaper and its depth effect; review of the black backdrop fix, 5)" "meth 'static void MLLayoutCoverParts(UIView *cv) {' | awk '/if \(MLPart\(kMLPartBackground\) && gBackdropImage\) \{/{a=NR} /MLFloatLayer\(YES\);/{b=NR} /\} else if \(gBackdrop\) MLBackdropDrop\(\);/{c=NR} END{exit !(a && b > a && c > b)}'"
check "the transient hint by the prominent display (16-18), the clock's method watch with its classes (the two clocks' gate audit)" "meth 'static void MLClockPlace(' | grep -qF 'UIView *th = MLProminentClock() ? MLTransientHint(MLProminent(cv)) : nil;' && meth 'static UIView *MLHintPicked(' | grep -qF 'MLProminentClock() ? MLIvar(MLProminent(cv), \"_transientSubtitleView\") : nil };' && [ \$(grep -c 'MLPartWatchBuild(&gWatch\[p\], p, MLProminentClock());' $X) = 3 ] && ! grep -q 'MLPartWatchBuild(&gWatch\[p\], p, gOS);' $X"
echo "== made-to-fail copies"
mut() {   # $1 name, $2 python replace (old), $3 (new)
  rm -rf "$W/m"; mkdir -p "$W/m"
  python3 -I -c "import sys; s=open(sys.argv[1]).read(); assert s.count(sys.argv[2])>=1, 'mutation not found: '+sys.argv[3]; open(sys.argv[4],'w').write(s.replace(sys.argv[2], sys.argv[5], 1))" "$H" "$2" "$1" "$W/m/h.h" "$3" || { echo "FAIL  made to fail ($1): the line to change is gone"; rc=1; return; }
  build "$W/m/h.h" "$W/m/t" >/dev/null || { echo "FAIL  made to fail ($1): did not build"; rc=1; return; }
  if "$W/m/t" > "$W/m/out" 2>&1; then echo "FAIL  made to fail ($1): the test still passes"; rc=1; else echo "PASS  made to fail ($1): caught ($(grep -c '^FAIL' "$W/m/out") checks)"; fi
}
mut "rev 1's 17/18 default (iPadOS's clock)" 'static inline int MLDefaultClockStyle(int osMajor) { (void)osMajor; return kMLClockMac; }' 'static inline int MLDefaultClockStyle(int osMajor) { return osMajor >= 17 ? kMLClockIPadOS : kMLClockMac; }'
mut "rev 2's Blurred default on 17/18 (a black Lock Screen there, 1.8.9 pass: the black backdrop)" 'static inline int MLDefaultBackground(int osMajor) { return osMajor >= 17 ? kMLBackWallpaper : kMLBackBlurred; }' 'static inline int MLDefaultBackground(int osMajor) { (void)osMajor; return kMLBackBlurred; }'
mut "the sharp wallpaper on 15/16 too" 'static inline int MLDefaultBackground(int osMajor) { return osMajor >= 17 ? kMLBackWallpaper : kMLBackBlurred; }' 'static inline int MLDefaultBackground(int osMajor) { (void)osMajor; return kMLBackWallpaper; }'
mut "Blurred offered on 17/18 with no still read (the fix round's build)" 'return osMajor < 17 || MLBoolOr(st[@"stillRead"], NO);' 'return YES;'
mut "Blurred never offered on 17/18, even after a real still" 'return osMajor < 17 || MLBoolOr(st[@"stillRead"], NO);' 'return osMajor < 17;'
mut "the empty-still guard off (the fix round's black backdrop drawn)" 'if (r[0] > 3 || r[1] > 3 || r[2] > 3) return NO;' 'if (r[0] > 3 || r[1] > 3 || r[2] > 3 || width) return NO;'
mut "the guard reads the first row only" 'for (size_t y = 0; y < height; y++) {' 'for (size_t y = 0; y < 1; y++) {'
mut "the guard reads alpha's byte (the context's unused byte)" 'if (r[0] > 3 || r[1] > 3 || r[2] > 3) return NO;' 'if (r[0] > 3 || r[1] > 3 || r[2] > 3 || r[3] > 3) return NO;'
mut "the backdrop key kept at v1 (the fix round's stored black pictures matched)" '@"v2 %@ %c %c %c"' '@"v1 %@ %c %c %c"'
mut "the respring Lock Screen ignores iPadOS read" 'm->lockFace = m->pendingLock || dismissedSinceLock == 0;' 'm->lockFace = m->pendingLock;'
mut "a wake with nothing down" 'if (m->down && (m->screenOff || dismissedSinceLock == 0)) m->lockFace = YES;' 'if (m->screenOff || dismissedSinceLock == 0) m->lockFace = YES;'
mut "a stale lock kept past the disappearance (the first pass)" 'static inline void MLOnGone(MLMachine *m) { m->down = NO; m->lockFace = NO; m->pendingLock = NO; }' 'static inline void MLOnGone(MLMachine *m) { m->down = NO; m->lockFace = NO; }'
mut "the master switch keeps a stale lock (the first pass)" 'static inline void MLOnMasterSwitch(MLMachine *m) { m->down = NO; m->lockFace = NO; m->pendingLock = NO; }' 'static inline void MLOnMasterSwitch(MLMachine *m) { m->down = NO; m->lockFace = NO; }'
mut "the switcher a flag only its cleanup clears (the first pass)" 'static inline void MLSwitcherEnd(MLSwitcherState *s) { s->pending = NO; s->sawPresenting = NO; }' 'static inline void MLSwitcherEnd(MLSwitcherState *s) { (void)s; }'
mut "the switcher ended by a read that never went YES" 'if (presenting) s->sawPresenting = YES; else if (s->sawPresenting) s->pending = NO;' 'if (!presenting) s->pending = NO;'
mut "the face formed during the switcher's zoom" 'return masterOn && appearing && !faceUp && !dismissing && !switcherPending && inWindowOnMainScreen;' 'return masterOn && appearing && !faceUp && !dismissing && inWindowOnMainScreen;'
mut "the first face only at -viewWillAppear: (the first pass)" 'return masterOn && appearing && !faceUp && !dismissing && !switcherPending && inWindowOnMainScreen;' 'return NO;'
mut "the time over a kept date line (review finding 1)" 'return keptLineBottom > 0 ? MAX(topLimit, keptLineBottom + MAX(2, round(0.006 * S))) : topLimit;' 'return topLimit + 0 * keptLineBottom * S;'
mut "no list yield" 'CGFloat top = MAX(listBottom > 0 ? listBottom : 0, topLimit);' 'CGFloat top = topLimit;'
mut "curly apostrophe kept" '@"\u2019s iPad"' '@"zz iPad"'
mut "day period kept" "if (!quoted && (c == 'a' || c == 'b' || c == 'B')) continue;" "if (!quoted && (c == 'b')) continue;"
mut "the clock not clamped to iPadOS's zone" 'for (int i = 0; i < 6 && zoneBottom > 0 && c.timeTop' 'for (int i = 0; i < 6 && 0 && c.timeTop'
mut "rev 2's estimated clock sizes (before the measured reference and the larger time)" 'c.dateSize = drawDate ? floor(round(0.028 * S) * k) : 0; c.timeSize = floor(round(0.15 * S) * k);' 'c.dateSize = drawDate ? floor(round(0.024 * S) * k) : 0; c.timeSize = floor(round(0.14 * S) * k);'
mut "the time placed by frames, not under the date's baseline" 'c.timeTop = round(c.top + c.dateSize * dm.asc + 0.027 * S * k - c.timeSize * (tm.asc - tm.cap));' 'c.timeTop = c.top + c.dateH + round(0.006 * S);'
mut "the date's top at 0.06 S (rev 2)" 'c.top = MAX(round(capTop - c.dateSize * (dm.asc - dm.cap)), topLimit);' 'c.top = MAX(round(0.06 * S), topLimit);'
mut "the tracking after the last glyph too" 'return plainWidth1 + (chars > 1 ? MLMacTimeKern(1) * (CGFloat)(chars - 1) : 0);' 'return plainWidth1 + MLMacTimeKern(1) * (CGFloat)chars;'
mut "the time untracked" 'static inline CGFloat MLMacTimeKern(CGFloat timeSize) { return -0.03 * timeSize; }' 'static inline CGFloat MLMacTimeKern(CGFloat timeSize) { return 0 * timeSize; }'
mut "the clock white 0.88 (rev 2)" '#define kMLClockWhiteAlpha 0.80' '#define kMLClockWhiteAlpha 0.88'
mut "the name at rev 2's 0.021 S" 'static inline CGFloat MLNameSize(CGSize screen) { return round(MIN(screen.width, screen.height) * 0.018); }' 'static inline CGFloat MLNameSize(CGSize screen) { return MAX(17, MIN(22, round(MIN(screen.width, screen.height) * 0.021))); }'
mut "the pair in iPadOS's order (Wi-Fi left)" 'if (wifiR) *wifiR = CGRectMake(battery.width + 10, 0, wifi.width, wifi.height);' 'if (wifiR) *wifiR = CGRectMake(0, 0, wifi.width, wifi.height);'
mut "the hint line at the capsule's text alpha" 'if (overOurBackdrop) return (MLTextLook){ 1.0, contrast ? 0.92 : 0.80, 0.0, 0.0 };' 'if (overOurBackdrop) return (MLTextLook){ 1.0, 0.92, 0.0, 0.0 };'
mut "rev 1's small picture" 'CGFloat s = MIN(screen.width, screen.height) * 0.09; return round(MAX(72, MIN(112, s)));' 'CGFloat s = MIN(screen.width, screen.height) * 0.075; return round(MAX(72, MIN(96, s)));'
mut "the hint line at 0.10 S over the cards (logic test BLOCKER 1)" 'CGFloat cy = CGRectIsEmpty(hintSlot) ? fallbackBottom - h / 2.0 : CGRectGetMidY(hintSlot);' 'CGFloat cy = fallbackBottom - h / 2.0;'
mut "the hint line over the home affordance" 'if (homeTop > 0 && y + h > homeTop - 4) y = homeTop - 4 - h;' ''
mut "the field never yields" 'return listBottom > 0 && listBottom >= CGRectGetMinY(field) - 8;' 'return NO;'
mut "the first hint, drawn or not (18.5's alpha-0 label)" 'if (h[i].drawn && h[i].hasText && h[i].alpha > 0.01) return i;' 'if (h[i].drawn) return i;'
mut "a stretched still (the first pass, landscape)" 'CGFloat k = MAX(dest.width / still.width, dest.height / still.height);' 'CGFloat k = dest.width / still.width;'
mut "a depth subject over the blur kept" 'return backdropShown && depthLayerPresent && depthLayerDrawn;' 'return NO;'
mut "a widget ignored" 'if (!MLRectMeetsAny(r, widgets, n)) return m;' 'if (!MLRectMeetsAny(r, widgets, 0)) return m;'
mut "rev 2's poster route only (-posterUUID, missing on 17.5.1 and 18.5: 1.8.9 pass: the black backdrop)" '?: MLUUIDText(MLTypedObj(cfg, sel_registerName("serverUUID")))
                  ?: MLUUIDText(MLTypedObj(ident, sel_registerName("posterUUID")));' ';'
mut "the poster's version not in its source (an edited poster kept its old picture)" 'BOOL hasVer = MLTypedUInt(cfg, sel_registerName("version"), &ver) || MLTypedUInt(ident, sel_registerName("version"), &ver);' 'BOOL hasVer = MLTypedUInt(cfg, sel_registerName("version"), &ver);'
mut "the date view's labels where the prominent display draws the clock (rev 2 on 16: two clocks, 1.8.9 pass: two clocks on 16)" '    if (prominent) return class_getInstanceVariable(prominent, "_timeView")' '    if (prominent && !dateView) return class_getInstanceVariable(prominent, "_timeView")'
[ $rc = 0 ] && echo "test-maclockscreen: all pass" || echo "test-maclockscreen: FAILED"
exit $rc
